{(filter!=="সব"||txCategoryFilter!=="সব ক্যাটাগরি"||txWalletFilter!=="সব ওয়ালেট"||txDateFilter!=="সব তারিখ"||txMonthFilter!=="সব মাস"||txMoreFilter!=="সব"||query)&&<button className="transaction-clear" onClick={()=>{setQuery("");setFilter("সব");setTxCategoryFilter("সব ক্যাটাগরি");setTxWalletFilter("সব ওয়ালেট");setTxDateFilter("সব তারিখ");setTxMonthFilter("সব মাস");setTxMoreFilter("সব");setTxSort("নতুন আগে");}}>সব মুছুন</button>}
