<div className="transaction-table-wrap dashboard-transaction-table-wrap"><div className="table-scroll"><table className="transaction-table dashboard-grouped-transactions"><thead><tr><th>সময়</th><th>ধরন</th><th>বিবরণ</th><th>ক্যাটাগরি</th><th>ওয়ালেট</th><th>পরিমাণ</th><th>ব্যালেন্স</th><th className="action-cell"/></tr></thead><tbody>{dashboardTransactionGroups.map(group=><Fragment key={group.date}><tr className="transaction-day-group"><td colSpan={8}><div className="transaction-day-header"><span className="transaction-day-title"><CalendarDays size={16}/><b>{group.date}</b><small>{group.count.toLocaleString("bn-BD")}টি লেনদেন</small></span><span className="transaction-day-totals"><span>আয়: <b>{money(group.income)}</b></span><span>ব্যয়: <b>{money(group.expense)}</b></span></span></div></td></tr>{group.items.map(t=><tr key={t.id}><td className="transaction-date-cell"><span className="transaction-date-text">{t.time||"—"}</span></td><td><span className={"transaction-kind kind-"+(t.kind==="আয়"?"income":t.kind==="ট্রান্সফার"?"transfer":"expense")}>{t.kind}</span></td><td className="transaction-description"><span className="record-name-with-icon"><span className="record-list-icon">{t.icon?renderManagedIcon(t.icon,17):t.title.slice(0,2)}</span><b>{t.title}</b></span></td><td><span className={"transaction-category category-"+(t.kind==="আয়"?"income":t.kind==="ট্রান্সফার"?"transfer":"expense")}>{t.category}</span></td><td><span className={"transaction-wallet transaction-wallet-brand wallet-brand-"+(t.wallet==="ব্যাংক"?"bank":t.wallet==="বিকাশ"?"bkash":t.wallet==="নগদ"?"nagad":"cash")}>{t.wallet==="বিকাশ"?<img className="transaction-wallet-logo transaction-wallet-logo-bkash" src="/bkash-mark.svg" alt="" aria-hidden="true"/>:(t.wallet==="নগদ")?<img className="transaction-wallet-logo transaction-wallet-logo-nagad" src="/nagad-mark.svg" alt="" aria-hidden="true"/>:t.wallet==="ব্যাংক"?<Landmark className="transaction-wallet-icon" aria-hidden="true"/>:<Wallet className="transaction-wallet-icon" aria-hidden="true"/>}<span>{t.wallet}{t.kind==="ট্রান্সফার"&&<span className="transfer-destination-inline"> → {t.transferTo}</span>}</span></span></td><td className={"transaction-amount "+(t.kind==="আয়"?"amount-in":t.kind==="ব্যয়"?"amount-out":"amount-transfer")}>{t.kind==="আয়"?"+":t.kind==="ব্যয়"?"−":"↔"} {money(t.amount)}</td><td className="transaction-balance">{money(transactionBalanceById[t.id]??balance)}</td><td className="action-cell"><div className="transaction-row-action"><button className="icon" onClick={()=>setOpenTxAction(openTxAction===t.id?null:t.id)} aria-label={t.title+" actions"} aria-expanded={openTxAction===t.id}><MoreHorizontal size={17}/></button>{openTxAction===t.id&&<div className="transaction-action-menu"><button onClick={()=>{editTransaction(t);setOpenTxAction(null)}}><Pencil size={14}/> সম্পাদনা</button><button className="danger-action" onClick={()=>{setOpenTxAction(null);removeTransaction(t.id)}}><X size={14}/> মুছে ফেলুন</button></div>}</div></td></tr>)}</Fragment>)}</tbody></table></div>{transactionFiltered.length===0&&<div className="empty">কোনো লেনদেন পাওয়া যায়নি</div>}</div>
