 const nextDueDate=(item:FeatureItem)=>{if(item.debtRule!=="installment"||!item.installmentAmount||!item.firstInstallmentDate)return item.date;const completed=Math.min(item.totalInstallments||Number.MAX_SAFE_INTEGER,Math.floor((paidAmount(item)+1e-8)/item.installmentAmount));return addInstallmentPeriods(item.firstInstallmentDate,completed,item.installmentFrequency||"monthly");};
 const nextBillDueDate=(item:FeatureItem)=>{if(!item.date||!item.billRule||item.billRule==="one-time")return "";const [year,month,day]=item.date.split("-").map(Number);let nextYear=year,nextMonth=month-1,targetDay=day;if(item.billRule==="weekly")return new Date(Date.UTC(year,month-1,day+7)).toISOString().slice(0,10);if(item.billRule==="monthly"){nextMonth+=1;targetDay=item.billDay||day;}else{nextYear+=1;targetDay=item.billDay||day;}if(nextMonth>11){nextYear+=Math.floor(nextMonth/12);nextMonth%=12;}const lastDay=new Date(Date.UTC(nextYear,nextMonth+1,0)).getUTCDate();return `${nextYear}-${String(nextMonth+1).padStart(2,"0")}-${String(Math.min(targetDay,lastDay)).padStart(2,"0")}`;};
 const selectedBill=active==="বিল"?items.find(x=>x.id===selectedBillId)||null:null;
