  <FeatureForm config={config!} icon={recordIcon} setIcon={setRecordIcon} show={showForm} formTitle={creditForm?"নতুন ক্রেডিট হিসাব":undefined} creditMode={creditForm} title={title} setTitle={setTitle} amount={amount} setAmount={setAmount} date={date} setDate={setDate} status={status} setStatus={setStatus} notes={notes} setNotes={setNotes} save={save} reset={reset} editing={editing} popup debtRule={debtRule} setDebtRule={setDebtRule} installmentAmount={installmentAmount} setInstallmentAmount={setInstallmentAmount} installmentFrequency={installmentFrequency} setInstallmentFrequency={setInstallmentFrequency} firstInstallmentDate={firstInstallmentDate} setFirstInstallmentDate={setFirstInstallmentDate}/>
