function IconPicker({value,onChange}:{value:string;onChange:(value:string)=>void}){const [open,setOpen]=useState(false);const selected=categoryIconChoices.find(item=>item.id===value);const root=useRef<HTMLDivElement>(null);useEffect(()=>{if(!open)return;const close=(event:MouseEvent)=>{if(root.current&&!root.current.contains(event.target as Node))setOpen(false)};document.addEventListener("mousedown",close);return()=>document.removeEventListener("mousedown",close)},[open]);return <div className={"icon-picker"+(open?" is-open":"")} ref={root}><button type="button" className="icon-picker-trigger" aria-label="আইকন নির্বাচন" aria-expanded={open} onClick={()=>setOpen(v=>!v)}>{selected?<selected.Icon size={21} strokeWidth={2.2}/>:<CircleHelp size={21}/>}</button>{open&&<div className="icon-picker-grid" role="group" aria-label="আইকন নির্বাচন">{categoryIconChoices.map(item=><button type="button" key={item.id} className={"icon-picker-option"+(value===item.id?" selected":"")} aria-label={item.label} title={item.label} aria-pressed={value===item.id} onClick={()=>{onChange(item.id);setOpen(false)}}><item.Icon size={20} strokeWidth={2.1}/></button>)}</div>}</div>;}

type ManagedCategory={id:number;name:string;type:"আয়"|"ব্যয়";icon:string;color:string;description:string};
const defaultManagedCategories:ManagedCategory[]=[
 {id:1,name:"বেতন",type:"আয়",icon:"💼",color:"#08a66b",description:""},
 {id:2,name:"ব্যবসার আয়",type:"আয়",icon:"🏪",color:"#08a66b",description:""},
 {id:3,name:"উপহার",type:"আয়",icon:"🎁",color:"#08a66b",description:""},
 {id:4,name:"বিনিয়োগ লাভ",type:"আয়",icon:"📊",color:"#08a66b",description:""},
 {id:5,name:"অন্যান্য",type:"আয়",icon:"•••",color:"#08a66b",description:""},
 {id:6,name:"বাজার",type:"ব্যয়",icon:"🛒",color:"#ef4444",description:""},
 {id:7,name:"বাসা ও ইউটিলিটি",type:"ব্যয়",icon:"⌂",color:"#ef4444",description:""},
 {id:8,name:"বিল",type:"ব্যয়",icon:"▤",color:"#ef4444",description:""},
 {id:9,name:"পরিবহন",type:"ব্যয়",icon:"🚘",color:"#ef4444",description:""},
 {id:10,name:"স্বাস্থ্য",type:"ব্যয়",icon:"♡",color:"#ef4444",description:""},
 {id:11,name:"শিক্ষা",type:"ব্যয়",icon:"🎓",color:"#ef4444",description:""},
 {id:12,name:"বিনোদন",type:"ব্যয়",icon:"▦",color:"#ef4444",description:""},
 {id:13,name:"অন্যান্য",type:"ব্যয়",icon:"•••",color:"#ef4444",description:""}
];
function readManagedCategories():ManagedCategory[]{try{const raw=localStorage.getItem("amar-hisab-managed-categories");if(raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))return parsed as ManagedCategory[];}}catch{}return defaultManagedCategories;}
function getTransactionCategories(type:"আয়"|"ব্যয়"){return readManagedCategories().filter(item=>item.type===type).map(item=>item.name);}
function CategoryManager({tx,setNotice}:{tx:Tx[];setNotice:(v:string)=>void}){
 const [categories,setCategories]=useState<ManagedCategory[]>(readManagedCategories);
 const [type,setType]=useState<"আয়"|"ব্যয়">("আয়");
 const [name,setName]=useState("");
 const [icon,setIcon]=useState("💼");
 const [color,setColor]=useState("#08a66b");
 const [description,setDescription]=useState("");
 const [editing,setEditing]=useState<number|null>(null);
 const [filter,setFilter]=useState<"সব"|"আয়"|"ব্যয়">("সব");
 const [search,setSearch]=useState("");
 const [sort,setSort]=useState("সম্প্রতি যোগ করা");
 const [iconSearch,setIconSearch]=useState("");
 const [iconGroup,setIconGroup]=useState("সব");
 const visibleIcons=useMemo(()=>categoryIconChoices.filter(item=>(iconGroup==="সব"||item.group===iconGroup)&&(item.label.toLowerCase().includes(iconSearch.toLowerCase())||item.id.toLowerCase().includes(iconSearch.toLowerCase()))),[iconGroup,iconSearch]);
 const colors=["#08a66b","#ff5b60","#4385f5","#8b5cf6","#fb923c","#fbbf24","#94a3b8","#22c5c5"];
 const counts=useMemo(()=>tx.reduce((a,t)=>({...a,[t.category]:(a[t.category]||0)+1}),{} as Record<string,number>),[tx]);
 const visible=useMemo(()=>categories.filter(c=>(filter==="সব"||c.type===filter)&&c.name.toLowerCase().includes(search.toLowerCase())).sort((a,b)=>sort==="নাম অনুযায়ী"?a.name.localeCompare(b.name,"bn"):0),[categories,filter,search,sort]);
 const reset=()=>{setName("");setIcon("💼");setColor(type==="আয়"?"#08a66b":"#ef4444");setDescription("");setEditing(null);};
 const chooseType=(v:"আয়"|"ব্যয়")=>{setType(v);setColor(v==="আয়"?"#08a66b":"#ef4444");};
 const save=(e:React.FormEvent)=>{e.preventDefault();const clean=name.trim();if(!clean){setNotice("ক্যাটাগরির নাম লিখুন।");return;}if(categories.some(c=>c.type===type&&c.name.toLowerCase()===clean.toLowerCase()&&c.id!==editing)){setNotice("এই ক্যাটাগরিটি আগে থেকেই আছে।");return;}const item:ManagedCategory={id:editing??Date.now(),name:clean,type,icon,color,description:description.trim()};const next=editing===null?[...categories,item]:categories.map(c=>c.id===editing?item:c);setCategories(next);try{localStorage.setItem("amar-hisab-managed-categories",JSON.stringify(next));}catch{}setNotice(editing===null?"নতুন ক্যাটাগরি যোগ হয়েছে।":"ক্যাটাগরি আপডেট হয়েছে।");reset();};
 const edit=(item:ManagedCategory)=>{setEditing(item.id);setType(item.type);setName(item.name);setIcon(item.icon);setColor(item.color);setDescription(item.description);};
 const remove=(item:ManagedCategory)=>{if((counts[item.name]||0)>0){setNotice("এই ক্যাটাগরিতে লেনদেন আছে, তাই এখন মুছতে পারবেন না।");return;}if(!window.confirm("“"+item.name+"” ক্যাটাগরিটি মুছে ফেলবেন?"))return;const next=categories.filter(c=>c.id!==item.id);setCategories(next);try{localStorage.setItem("amar-hisab-managed-categories",JSON.stringify(next));}catch{}if(editing===item.id)reset();setNotice("ক্যাটাগরি মুছে ফেলা হয়েছে।");};
 const list=(listType:"আয়"|"ব্যয়")=>visible.filter(c=>c.type===listType);
 return <section className="category-manager-page">
  <div className="category-manager-hero"><div><h2>ক্যাটাগরি ম্যানেজার</h2><p>আপনার আয় ও ব্যয়ের ক্যাটাগরি তৈরি, সম্পাদনা এবং পরিচালনা করুন।</p></div><div className="category-manager-summary"><div className="category-summary-income"><span>↗</span><div><small>মোট আয় ক্যাটাগরি</small><strong>{categories.filter(c=>c.type==="আয়").length.toLocaleString("bn-BD")}</strong></div></div><div className="category-summary-expense"><span>↘</span><div><small>মোট ব্যয় ক্যাটাগরি</small><strong>{categories.filter(c=>c.type==="ব্যয়").length.toLocaleString("bn-BD")}</strong></div></div></div></div>
  <div className="category-manager-toolbar"><div className="category-manager-filters">{(["সব","আয়","ব্যয়"] as const).map(v=><button key={v} className={filter===v?"active "+(v==="ব্যয়"?"expense":"income"):""} onClick={()=>setFilter(v)}>{v==="সব"?"সব ক্যাটাগরি":v} ({v==="সব"?categories.length:categories.filter(c=>c.type===v).length})</button>)}</div><label className="category-manager-search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="ক্যাটাগরি খুঁজুন..."/></label><AppSelect className="category-manager-sort" value={sort} ariaLabel="ক্যাটাগরি সাজানো" onChange={setSort} options={[{value:"সম্প্রতি যোগ করা",label:"সম্প্রতি যোগ করা"},{value:"নাম অনুযায়ী",label:"নাম অনুযায়ী"}]}/></div>
  <div className="category-manager-grid"><section className="category-manager-list-card income-card"><div className="category-manager-card-heading"><span className="category-type-icon">↗</span><div><h3>আয় ক্যাটাগরি</h3><p>আয়ের উৎসের ক্যাটাগরিগুলো এখানে দেখানো হয়েছে।</p></div></div><div className="category-manager-table-head"><span>নাম</span><span>লেনদেন সংখ্যা</span><span>অ্যাকশন</span></div>{list("আয়").map(c=><div className="managed-category-row" key={c.id}><span className="managed-category-icon" style={{color:c.color,background:c.color+"18"}}>{renderManagedIcon(c.icon,20)}</span><span className="managed-category-name">{c.name}</span><span className="managed-category-count">{(counts[c.name]||0).toLocaleString("bn-BD")}</span><span className="managed-category-actions"><button className="category-edit-btn" onClick={()=>edit(c)} aria-label="সম্পাদনা"><Pencil size={16}/></button><button className="category-delete-btn" onClick={()=>remove(c)} aria-label="মুছুন"><X size={16}/></button></span></div>)}{list("আয়").length===0&&<p className="category-empty">কোনো আয় ক্যাটাগরি পাওয়া যায়নি।</p>}</section>
  <section className="category-manager-list-card expense-card"><div className="category-manager-card-heading"><span className="category-type-icon">↘</span><div><h3>ব্যয় ক্যাটাগরি</h3><p>ব্যয়ের খাতের ক্যাটাগরিগুলো এখানে দেখানো হয়েছে।</p></div></div><div className="category-manager-table-head"><span>নাম</span><span>লেনদেন সংখ্যা</span><span>অ্যাকশন</span></div>{list("ব্যয়").map(c=><div className="managed-category-row" key={c.id}><span className="managed-category-icon" style={{color:c.color,background:c.color+"18"}}>{renderManagedIcon(c.icon,20)}</span><span className="managed-category-name">{c.name}</span><span className="managed-category-count">{(counts[c.name]||0).toLocaleString("bn-BD")}</span><span className="managed-category-actions"><button className="category-edit-btn" onClick={()=>edit(c)} aria-label="সম্পাদনা"><Pencil size={16}/></button><button className="category-delete-btn" onClick={()=>remove(c)} aria-label="মুছুন"><X size={16}/></button></span></div>)}{list("ব্যয়").length===0&&<p className="category-empty">কোনো ব্যয় ক্যাটাগরি পাওয়া যায়নি।</p>}</section>
  <aside className="category-manager-editor"><div className="category-editor-heading"><h3>{editing===null?"নতুন ক্যাটাগরি যোগ করুন":"ক্যাটাগরি সম্পাদনা"}</h3>{editing!==null&&<button className="category-editor-close" onClick={reset} aria-label="ফর্ম রিসেট"><X size={18}/></button>}</div><form onSubmit={save}><label>ক্যাটাগরির ধরন <b>*</b></label><div className="category-type-switch"><button type="button" className={type==="আয়"?"selected income":"income"} onClick={()=>chooseType("আয়")}>↗ &nbsp; আয়</button><button type="button" className={type==="ব্যয়"?"selected expense":"expense"} onClick={()=>chooseType("ব্যয়")}>↘ &nbsp; ব্যয়</button></div><label>ক্যাটাগরির নাম <b>*</b><input required value={name} onChange={e=>setName(e.target.value)} placeholder="যেমন: বেতন, বাজার, ভাড়া"/></label><label>আইকন</label><label className="category-icon-search"><Search size={15}/><input value={iconSearch} onChange={e=>setIconSearch(e.target.value)} placeholder="আইকন খুঁজুন..."/></label><div className="category-icon-groups">{["সব","অর্থ","কেনাকাটা","বাসা","প্রযুক্তি","যাতায়াত","খাবার","স্বাস্থ্য","শিক্ষা","বিনোদন","পোষা প্রাণী","ব্যক্তিগত","প্রকৃতি","অন্যান্য"].map(group=><button type="button" key={group} className={iconGroup===group?"active":""} onClick={()=>setIconGroup(group)}>{group}</button>)}</div><div className="category-icon-choices">{visibleIcons.map(item=><button type="button" key={item.id} title={item.label} aria-label={item.label} className={icon===item.id?"chosen":""} onClick={()=>setIcon(item.id)}><item.Icon size={19} strokeWidth={2}/></button>)}</div><p className="category-icon-selected">নির্বাচিত: {categoryIconChoices.find(item=>item.id===icon)?.label??"পুরোনো আইকন"}</p><label>রং</label><div className="category-color-choices">{colors.map(v=><button type="button" key={v} aria-label={"রং "+v} className={color===v?"chosen":""} style={{background:v}} onClick={()=>setColor(v)}/>)}</div><label>বিবরণ (ঐচ্ছিক)<textarea value={description} onChange={e=>setDescription(e.target.value)} placeholder="এই ক্যাটাগরি সম্পর্কে সংক্ষিপ্ত বিবরণ লিখুন..."/></label><div className="category-editor-actions"><button type="button" className="btn secondary" onClick={reset}>বাতিল</button><button type="submit" className="btn primary"><Check size={16}/>{editing===null?"ক্যাটাগরি সংরক্ষণ":"পরিবর্তন সংরক্ষণ"}</button></div></form></aside></div>
 </section>;
}


function FeatureRecords({items,edit,remove}:{items:FeatureItem[];edit:(x:FeatureItem)=>void;remove:(id:number)=>void}){return <div className="table-scroll"><table><thead><tr><th>বিবরণ</th><th>তারিখ</th><th>অবস্থা/নোট</th><th>পরিমাণ</th><th>অ্যাকশন</th></tr></thead><tbody>{items.map(x=><tr key={x.id}><td><div className="record-name-with-icon"><span className="record-list-icon">{x.icon?renderManagedIcon(x.icon,18):x.title.slice(0,2)}</span><b>{x.title}</b></div></td><td>{x.date||"—"}</td><td><span className="tag">{x.status||"—"}</span>{x.notes&&<small className="subline">{x.notes}</small>}</td><td>{money(x.amount)}</td><td><div className="row-actions"><button className="icon" onClick={()=>edit(x)} aria-label="সম্পাদনা"><Pencil size={15}/></button><button className="icon" onClick={()=>remove(x.id)} aria-label="মুছুন"><X size={15}/></button></div></td></tr>)}</tbody></table></div>}
function FeatureForm({config,icon,setIcon,show,formTitle,creditMode=false,title,setTitle,amount,setAmount,date,setDate,status,setStatus,notes,setNotes,save,reset,editing,popup=false,debtRule="one-time",setDebtRule=()=>{},installmentAmount="",setInstallmentAmount=()=>{},installmentFrequency="monthly",setInstallmentFrequency=()=>{},firstInstallmentDate="",setFirstInstallmentDate=()=>{},billRule="one-time",setBillRule=()=>{},reminderDays="3",setReminderDays=()=>{}}:{config:{key:string;title:string;description:string;add:string;fields:string[]};icon:string;setIcon:(v:string)=>void;show:boolean;formTitle?:string;creditMode?:boolean;title:string;setTitle:(v:string)=>void;amount:string;setAmount:(v:string)=>void;date:string;setDate:(v:string)=>void;status:string;setStatus:(v:string)=>void;notes:string;setNotes:(v:string)=>void;save:(e:React.FormEvent)=>void;reset:()=>void;editing:number|null;popup?:boolean;debtRule?:"one-time"|"installment";setDebtRule?:(v:"one-time"|"installment")=>void;installmentAmount?:string;setInstallmentAmount?:(v:string)=>void;installmentFrequency?:"weekly"|"monthly";setInstallmentFrequency?:(v:"weekly"|"monthly")=>void;firstInstallmentDate?:string;setFirstInstallmentDate?:(v:string)=>void;billRule?:"one-time"|"weekly"|"monthly"|"yearly";setBillRule?:(v:"one-time"|"weekly"|"monthly"|"yearly")=>void;reminderDays?:string;setReminderDays?:(v:string)=>void}){if(!show)return null;const form=<section className="panel feature-form-panel"><div className="panel-title"><div><h3>{editing===null?(formTitle||config.add):"রেকর্ড সম্পাদনা"}</h3><p>তথ্য এই browser-এ সংরক্ষণ হবে।</p></div><button type="button" className="icon" onClick={reset} aria-label="ফর্ম বন্ধ করুন"><X/></button></div><form className="feature-form" onSubmit={save}><label>{config.fields[0]}<input required value={title} onChange={e=>setTitle(e.target.value)} placeholder="নাম বা বিবরণ"/></label><label className="record-icon-field">আইকন নির্বাচন <div className="record-icon-picker"><span className="record-icon-preview">{renderManagedIcon(icon,22)}</span><IconPicker value={icon} onChange={setIcon}/></div></label>{!(creditMode&&config.key==="debts")&&<label>{config.key==="debts"?"মোট দেনা/পাওনা (৳)":config.fields[1]}<input required type="number" min="0.01" step="0.01" value={amount} onChange={e=>setAmount(e.target.value)} placeholder="৳ 0"/></label>}{config.key==="debts"&&<label>হিসাবের নিয়ম<AppSelect value={debtRule} ariaLabel="হিসাবের নিয়ম" onChange={v=>setDebtRule(v as "one-time"|"installment")} options={[{value:"one-time",label:"সহজ হিসাব (একবার)"},{value:"installment",label:creditMode?"মাসিক হিসাব":"কিস্তির হিসাব"}]}/></label>}{config.key==="debts"&&debtRule==="installment"?<>{!creditMode&&<label>প্রতি কিস্তির পরিমাণ (৳)<input required type="number" min="0.01" step="0.01" max={amount||undefined} value={installmentAmount} onChange={e=>setInstallmentAmount(e.target.value)} placeholder="৳ 0"/></label>}<label>কিস্তির বিরতি<AppSelect value={installmentFrequency} ariaLabel="কিস্তির বিরতি" onChange={v=>setInstallmentFrequency(v as "weekly"|"monthly")} options={[{value:"weekly",label:"প্রতি সপ্তাহে"},{value:"monthly",label:"প্রতি মাসে"}]}/></label><label>প্রথম কিস্তির তারিখ (দিন/মাস/বছর)<input required type="date" value={firstInstallmentDate||date} onChange={e=>{setFirstInstallmentDate(e.target.value);setDate(e.target.value)}}/><small className="date-format-help">তারিখ নির্বাচন করুন। Save করার আগে তারিখ যাচাই হবে।</small></label>{!creditMode&&<div className="installment-summary"><small>মোট কিস্তি</small><strong>{Number(amount)>0&&Number(installmentAmount)>0&&Number(installmentAmount)<=Number(amount)?Math.ceil(Number(amount)/Number(installmentAmount)).toLocaleString("bn-BD"):"—"}টি</strong><small>শেষ কিস্তি প্রয়োজন অনুযায়ী কম হতে পারে</small></div>}</>:<label>{config.fields[2]} (দিন/মাস/বছর)<input type="date" required value={date} onChange={e=>setDate(e.target.value)}/><small className="date-format-help">তারিখ নির্বাচন করুন। Save করার আগে তারিখ যাচাই হবে।</small></label>}{config.key==="bills"&&<><label>বিলের পুনরাবৃত্তি<AppSelect value={billRule} ariaLabel="বিলের পুনরাবৃত্তি" onChange={v=>setBillRule(v as "one-time"|"weekly"|"monthly"|"yearly")} options={[{value:"one-time",label:"একবার"},{value:"weekly",label:"প্রতি সপ্তাহে"},{value:"monthly",label:"প্রতি মাসে"},{value:"yearly",label:"প্রতি বছরে"}]}/></label><label>রিমাইন্ডার<AppSelect value={reminderDays} ariaLabel="রিমাইন্ডার" onChange={setReminderDays} options={[{value:"0",label:"রিমাইন্ডার বন্ধ"},{value:"1",label:"১ দিন আগে"},{value:"3",label:"৩ দিন আগে"},{value:"7",label:"৭ দিন আগে"},{value:"14",label:"১৪ দিন আগে"}]}/></label></>}<label>{config.fields[3]}<AppSelect value={status} ariaLabel="অবস্থা" onChange={setStatus} options={["চলমান","বাকি","পরিশোধিত","পাওনা","দেনা","সম্পন্ন","সঞ্চয়","অন্যান্য"].map(x=>({value:x,label:x}))}/></label><label className="wide">{config.fields[4]}<input value={notes} onChange={e=>setNotes(e.target.value)} placeholder="ঐচ্ছিক নোট"/></label><div className="wide modal-actions"><button type="button" className="btn secondary" onClick={reset}>বাতিল</button><button className="btn primary"><Check/> সংরক্ষণ</button></div></form></section>;if(!popup)return form;return <AnimatePresence>{show&&<motion.div className="modal-shade feature-form-shade" initial={{opacity:0}} animate={{opacity:1}} exit={{opacity:0}} onMouseDown={e=>{if(e.target===e.currentTarget)reset()}}><motion.div className="feature-form-modal" role="dialog" aria-modal="true" aria-labelledby="feature-form-title" initial={{opacity:0,y:15,scale:.98}} animate={{opacity:1,y:0,scale:1}} exit={{opacity:0,y:10,scale:.98}} transition={{duration:.18,ease:"easeOut"}}>{form}</motion.div></motion.div>}</AnimatePresence>}

function WalletBox({name,amount}:{name:string;amount:number}){const displayName=name;const Icon=name==="ক্যাশ"?Banknote:name==="ব্যাংক"?Landmark:Wallet;const logo=name==="বিকাশ"?"/bkash-mark.svg":name==="নগদ"?"/nagad-mark.svg":null;const cssName=name==="ক্যাশ"?"cash":name==="ব্যাংক"?"bank":name==="বিকাশ"?"bkash":"nagad";return <div className={"wallet-box wallet-"+cssName}><span className={"wallet-brand-icon "+(name==="বিকাশ"?"bkash-brand":name==="নগদ"?"nagad-brand":"")}>{logo?<img src={logo} alt={name+" logo"}/>:<Icon/>}</span><div className="wallet-info"><b>{displayName}</b><strong>{money(amount)}</strong></div></div>}
